local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[2986] = { title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, $N.", objectives = "Sucht Islen Waterseer im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2987] = { title = "Gordunnikobalt", description = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.\n\nWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!", objectives = "Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2988] = { title = "Käfige der Witherbark", description = "Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.\n\nIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Witherbarktrolle, um herauszufinden, ob Scharfschnabel dort ist.", objectives = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2989] = { title = "Der Altar von Zul", description = "Scharfschnabel war nicht bei den Witherbarktrollen. Vielleicht haben ihn die Vilebranchtrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Vilebranch und sucht nach dem Greifenjungen.", objectives = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2990] = { title = "Thadius Grimmschatten", description = "Bringt diese Feder zum Rutengänger Thadius Grimshade. Er verließ vor Jahren Aerie Peak, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!\n\nUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.\n\nDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.\n\nViel Glück, $N. Ihr werdet Thadius in den verwüsteten Landen finden, im Magierturm der Burg Nethergarde.", objectives = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2991] = { title = "Nekrums Medaillon", description = "Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.\n\nZul’Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.", objectives = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2992] = { title = "Der Rutengang", description = "Lasst mir etwas Platz, während ich ein Rutengangritual durchführe. Ich werde die Verbindung zwischen der Feder, die Ihr mir gebracht habt, und ihrem Besitzer herstellen und dann selbst dieser Verbindung zu Scharfschnabel folgen.\n\nZumindest... wenn alles nach Plan verläuft. Wenn nicht, nun... dann schließt Ihr besser die Augen.", objectives = "Wartet, bis Grimshade das Rutengangritual durchgeführt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2993] = { title = "Rückkehr ins Hinterland", description = "Scharfschnabel wird in einem Käfig hoch oben auf einer Klippe am Gipfel des Jintha’Alor im Hinterland gefangen gehalten. Der Schlüssel zu diesem Käfig ist im Besitz der Hohepriesterin der Vilebranchtrolle, der üblen Priesterin Hexx.\n\nDa. Ich habe meinen Teil erfüllt. Ich wünsche Euch Glück, $N.", objectives = "Sprecht mit Greifenmeister Talonaxe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2994] = { title = "Scharfschnabels Rettung", description = "Wir müssen Scharfschnabel retten!\n\nKämpft Euch bis zum Gipfel von Jintha’Alor im Herzen des Vilebranchterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.", objectives = "Kämpft Euch bis zum Gipfel von Jintha’Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2995] = { title = "Nachrichtenwege", description = "Die Quel'Danil-Hütte ist ein Zentrum der Kommunikation für die Hochelfen des Hinterlands. Ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die Trolle der Witherbark teilen, die das Gebiet im südlichen Hinterland bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.\n\nWir können es nicht brauchen, wenn die Hochtalelfen Allianzen mit anderen schließen, $N.\n\nVernichtet die Hochtaldokumente. Wir müssen ihre Nachrichtenwege niederbrennen... im wahrsten Sinne des Wortes.", objectives = "Oran Snakewrithe in Undercity will, dass Ihr ins Hinterland reist und die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen verbrennt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2996] = { title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten. Er mag klein sein, aber er ist auch mächtig. Er kann Euch mächtigere Beschwörungen lehren - ich fühle, dass Ihr dazu bereit seid. Geht nun zu ihm. Er ist in Ratchet... Über der Hafenstadt gleich bei seinem Turm.", objectives = "Sprecht mit Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2997] = { title = "Foliant der Offenbarung", description = "Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr Euch auf den Weg nach Ironforge hinauf machen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.\n\nIhr könnt sie oben in der Halle der Mysterien finden. Falls Ihr noch nie dort wart, das ist im Mystikerviertel. Viel Glück, $N.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2998] = { title = "Foliant der Offenbarung", description = "Seid gegrüßt, $GBruder:Schwester;. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.\n\nWenn ich Ihr wäre, würde ich nach Stormwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[2999] = { title = "Foliant der Offenbarung", description = "Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3000] = { title = "Foliant der Offenbarung", description = "Hallo, $N. Ich weiß, Ihr seid damit beschäftigt, den Völkern Azeroths zu helfen, aber wenn Ihr etwas Zeit habt, solltet Ihr nach Ironforge zurückkehren, um mit einem der am meisten respektierten Paladine Eurer Heimat zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Zwergen-Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von uns allen erwartet wird.\n\nIhr findet sie im Obergeschoss der Halle der Mysterien, die sich im Mystikerviertel befindet.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3001] = { title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten oder als Euren Feind anzusehen - zumindest vorerst. Er ist mächtig und sollte respektiert werden. Er kann Euch große Beschwörungen lehren, Beschwörungen, für die Ihr, glaube ich, bereit seid. Geht nun zu ihm.\n\nEr ist in Ratchet... Über der Hafenstadt, gleich bei dem Turm dort.", objectives = "Findet Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3002] = { title = "Die Gordunnikugel", description = "Obwohl ich meinen Feind genau kenne, bin ich ein Krieger, $n. Ich kann Euch nicht sagen, über welche Fähigkeiten diese Kugel verfügt.\n\nIch kenne einen Magier in Orgrimmar, der uns mehr über die Kugel sagen können wird. Bringt sie zu ihm.", objectives = "Bringt die Gordunnikugel zu Uthel’nay in die Dunkeldornen-Lodge in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3022] = { title = "Vorsichtig behandeln", description = "$N, ich sehe deutlich, dass Ihr Euch liebend gern meiner noblen Sache zuwenden möchtet. Ja, natürlich könnt Ihr etwas für mich tun!\n\nBringt diese Kiste mit Eiern zu Erelas Ambersky. Das ist ein Druide, der sich um diese Eier kümmert. Er bebrütet sie und bildet dann die jungen Hippogryphe aus. Ihr findet ihn in Teldrassil, in einem kleinen Dorf im Süden namens Rut'theran.", objectives = "Bringt die sorgfältig verpackte Kiste zu Erelas Ambersky in das Dorf Rut'theran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3042] = { title = "Trollaushärter", description = "Die Trolle der Sandfury von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.\n\nZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.", objectives = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3062] = { title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", objectives = "Talo Thornhoof im Camp Mojache will das dunkle Herz von Edana Hasskralle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3063] = { title = "Rache an den Nordschwingen", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. $n, rächt mich.", objectives = "Talo Thornhoof möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3065] = { title = "Einfache Schrifttafel", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", objectives = "Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3082] = { title = "Geätzte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Sprecht mit Jen'shan im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3083] = { title = "Verschlüsselte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3084] = { title = "Mit Runen beschriftete Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Sprecht mit Shikrik im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3085] = { title = "Geheiligte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3086] = { title = "Glyphen-Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, $n.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3087] = { title = "Geätztes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $N.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3088] = { title = "Verschlüsseltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3089] = { title = "Mit Runen beschriftetes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3090] = { title = "Besudeltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, $n.\n\nIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", objectives = "Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3091] = { title = "Einfache Notiz", description = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.", objectives = "Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3092] = { title = "Geätzte Notiz", description = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.", objectives = "Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3093] = { title = "Mit Runen beschriftete Notiz", description = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.", objectives = "Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3094] = { title = "Tiefgrüne Notiz", description = "Gerade eben fragte eine Botin nach Euch, $n. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.", objectives = "Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3095] = { title = "Einfache Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", objectives = "Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3096] = { title = "Verschlüsselte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", objectives = "Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3097] = { title = "Geheiligte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", objectives = "Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3098] = { title = "Glyphen-Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magielehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", objectives = "Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3099] = { title = "Besudelte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", objectives = "Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3100] = { title = "Einfacher Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3101] = { title = "Geweihter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3102] = { title = "Verschlüsselter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Jorik, einem unserer örtlichen Lehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3103] = { title = "Geheiligter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien der Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3104] = { title = "Glyphen-Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Kheldon, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3105] = { title = "Besudelter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, $N. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Lehrerinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", objectives = "Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3106] = { title = "Einfache Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3107] = { title = "Geweihte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Paladinlehrer Bromos. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3108] = { title = "Geätzte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Jägerlehrer Thorgas. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3109] = { title = "Verschlüsselte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3110] = { title = "Geheiligte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3112] = { title = "Einfaches Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3113] = { title = "Verschlüsseltes Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3114] = { title = "Glyphen-Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magielehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", objectives = "Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3115] = { title = "Besudeltes Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrer Alamar. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.\n\nUnd passt auf Euch auf, $N, man traut Leuten wie Euch hierzulande nicht gerade.", objectives = "Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3116] = { title = "Einfaches Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", objectives = "Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3117] = { title = "Geätztes Siegelzeichen", description = "Dieses Siegelzeichen  wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", objectives = "Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3118] = { title = "Verschlüsselte Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Schurkenlehrerin Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", objectives = "Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3119] = { title = "Geheiligtes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", objectives = "Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3120] = { title = "Tiefgrünes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.", objectives = "Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3121] = { title = "Eine seltsame Anforderung", description = "Neeru Fireblade in Orgrimmar hat, was ich brauche, um hier beginnen zu können! Er hat ein Gebräu zusammengemischt, das ich für mein... na, Ihr werdet es schon sehen.\n\nAb mit Euch... nach Orgrimmar. Hier, nehmt das mit. Es ist ein Schrumpfkopf, den ich Neeru im Tausch für die Kräuter versprochen habe. Es ist der Kopf eines armen Zwergs, der mir im Wald über den Weg gelaufen ist. Ich bin sicher, dass Neeru sehr erfreut sein wird.\n\nIhr werdet Neeru in der Kluft der Schatten finden.", objectives = "Bringt den Schrumpfkopf zu Neeru Fireblade in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3122] = { title = "Kehrt zu Hexendoktor Uzer'i zurück", description = "Hier sind die Kräuter, $n. Bringt sie zu Hexendoktor Uzer'i.\n\nUnd sagt ihm, dass ich mit dem Schrumpfkopf sehr zufrieden bin.", objectives = "Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3123] = { title = "Das Gefäß wird getestet", description = "Dies ist ein Test, sowohl für das Ritual, das ich durchgeführt habe, als auch für Eure Fähigkeiten. Nehmt dieses Gefäß, $N. Damit habt Ihr die Macht, eine Kreatur zu schrumpfen und sie darin gefangen zu nehmen.\n\nReist ins Hinterland und sucht nach Kreaturen, die als Wildekin bekannt sind. Sie waren einst die Tiere der Nachtelfengöttin Elune. Die heimtückischen, primitiven oder wilden Eulenbestien sollen Euer Ziel sein, $N. Vernichtet 10 und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihr Geist flüchten kann.", objectives = "Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.\n\nBringt anschließend 10 Einheiten Muisek von Wildekins und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3124] = { title = "Muisek von Hippogryphen", description = "Da Ihr bewiesen habt, dass Ihr vertrauenswürdig und auch in der Lage seid, das Muisekgefäß zu benutzen, möchte ich, dass Ihr eine weitere Kreatur einfangt.\n\nHippogryphen sind seit vielen Jahren die treuen Gefährten der Nachtelfen. Ihre Geister sind loyal und unerschütterlich.\n\nEure Aufgabe besteht darin, 10 Fransenfederhippogryphen auszuschalten, sie schnell zu schrumpfen und mit dem Gefäß einzufangen, sodass ihr Muisek erhalten bleibt. Ihr findet die Hippogryphen in der Oberen Wildnis, südlich von hier.", objectives = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3125] = { title = "Muisek von Feendrachen", description = "$n, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, $n. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", objectives = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3126] = { title = "Muisek von Treants", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, $n. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet 3 umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", objectives = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3127] = { title = "Muisek von Bergriesen", description = "Bei der letzten Aufgabe, die ich Euch stelle, sollt Ihr nach Nordwesten reisen und den letzten Feind finden.\n\nAls die Brennende Legion in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den Nachtelfen zu helfen. Ihr erkennt sie an ihrer enormen Größe und daran, wie der Boden erzittert, wenn Ihr durch ihr felsiges Gelände reist.\n\nIch kann es kaum erwarten, eine Macht von dieser Größe zu zähmen. Schaltet 7 Bergriesen aus und benutzt dann das Muisekgefäß, um ihr mächtiges Muisek einzufangen.", objectives = "Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3128] = { title = "Natürliche Materialien", description = "Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.\n\nIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphs von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.", objectives = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3129] = { title = "Waffen des Geistes", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", objectives = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3130] = { title = "Gegen die Hasskämme", description = "Ich werde Euch jetzt zu meinem Stellvertreter Lactronicus schicken. Er hat bisher ein wachsames Auge auf die Nagastreitkräfte gehabt. Ich werde die allgemeine Lage hier in Bezug auf die Naga bewerten. Liebend gern würde ich eine ganze Armee gegen sie aussenden, aber es ist nicht unbedingt ratsam, die Festung einem direkten Angriff der Horde - oder Schlimmerem - schutzlos auszusetzen.\n\nWie dem auch sei, Latronicus erwartet Euch. Gute Arbeit bisher, $n. Nur weiter so.\n\nIhr könnt wegtreten.", objectives = "Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3141] = { title = "Loramus", description = "Ihr wollt also gegen Dämonen kämpfen? Dann tätet Ihr gut daran, Euch meine Geschichte anzuhören.", objectives = "Lasst Loramus Thalipedes seine Geschichte erzählen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3161] = { title = "Gahz'ridian", description = "$N, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher!\n\nVor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das ich nach der Hydragöttin \"Gahz'ridian\" nenne.\n\nIch selbst habe schon einige dieser Ornamente gefunden, aber ich hätte gern noch mehr, um sie zu untersuchen - vielleicht findet Ihr ja noch welche ...\n\nIch habe sogar einen Detektor erfunden, der es zu einem Kinderspiel macht, Gahz'ridian zu finden! Legt ihn einfach an und die Suche kann beginnen!", objectives = "Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3181] = { title = "Das Horn der Bestie", description = "Das gigantische Horn hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest.\n\nBeim näheren Hinschauen entdeckt Ihr, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt:\n\nEigentum von Gebirgsjägerin Pebblebitty.\n\nAls Ihr versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.\n\nUps!", objectives = "Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3182] = { title = "Besitznachweis", description = "Ihr erwartet wirklich, dass ich eine solche Geschichte glaube? Wenn es das echte Horn wäre, dann würde meine zerbrochene Axt ja immer noch drinstecken.\n\nHört zu, bringt diese dreiste Fälschung zu Kurator Thorius in Ironforge. Falls er Eure Behauptung bestätigt, werdet Ihr eine Beweisurkunde für Eure Tat erhalten. Bringt mir diesen Beweis und ich werde Euch den Schlüssel für die sengende Schlucht geben.\n\nGeht schon!", objectives = "Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3201] = { title = "Endlich!", description = "Ich kann kaum glauben, dass Pebblebitty die Echtheit des Horns angezweifelt hat. Unter uns, ich denke, sie ist einfach nur eifersüchtig. Ich weiß, dass sie diese Bestie gern selbst getötet hätte, nach dem, was bei dem 'Ereignis' so vorgefallen ist.\n\nIhr braucht also eine Urkunde für Eure Tat? Nachdem Ihr nun gerade dem Museum ein solches Geschenk gemacht habt, sollte das kein Problem sein.\n\n<Kurator Thorius fängt an, ein großes Dokument auszufüllen.>\n\nHier bitte! Das könnt Ihr Pebblebitty zurückbringen.", objectives = "Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3221] = { title = "Sprecht mit Renferrel", description = "Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.", objectives = "Sprecht mit Apotheker Renferrel in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3261] = { title = "Jorn Himmelsdeuter", description = "Eure Zeit bei mir ist vorbei, $N. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Skyseer sprechen. Er wird Eure Weiterbildung übernehmen.", objectives = "Sprecht im Camp Taurajo mit Jorn Skyseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3281] = { title = "Gestohlenes Silber", description = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.\n\nGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.", objectives = "Bringt das gestohlene Silber zu Gazrog in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3301] = { title = "Mura Runentotem", description = "Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.\n\nBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.", objectives = "Sprecht mit Mura Runetotem in dem Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3321] = { title = "Habt Ihr das verloren?", description = "Ihr habt viel für den Orden getan, $n. Allein die Hingabe, derer es bedarf, um hierher zu gelangen, hätte jede normale Person abgehalten. Galvan und auch ich haben keinerlei Zweifel, dass Ihr einer von uns seid.\n\nAus diesem Grund denke ich, dass Ihr Euch eine kleine Belohnung verdient habt. Es ist nichts Besonderes, nur eine Kleinigkeit. Vielleicht sind Euch seine Eigenschaften vertraut, denn ich glaube, dass es der Grund war, warum Ihr überhaupt zu uns gekommen seid.", objectives = "Wartet, bis Trenton seine Arbeit erledigt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3341] = { title = "Das Ende bringen", description = "Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel von Razorfen genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...\n\nDie Stacheleber der Hügel von Razorfen haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.\n\nAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, $N. Dem Kältebringer muss ein Ende gemacht werden.", objectives = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3361] = { title = "Dilemma eines Flüchtlings", description = "Wir haben die Troggs aus Gnomeregan vertrieben, aber dann ist alles schrecklich schief gegangen! Jetzt ist unsere Heimat völlig von Strahlen verseucht und wir Gnome sind überall in Dun Morogh zerstreut.\n\nIn meiner Hast, der Strahlung zu entkommen, habe ich all mein ganzes Hab und Gut und auch meine Werkzeuge verloren. Die Trolle haben sie geholt. Sie haben meine Truhe, meine Kiste, und meinen Bolzeneimer gestohlen! Alles das haben sie in ihre Lager südwestlich von Anvilmar mitgenommen.\n\nIch bin nur leider kein Abenteurer - könntet Ihr bitte meine Sachen suchen und sie mir herbringen?", objectives = "Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3362] = { title = "Disteltal", description = "Habt Ihr jemals das Disteltal gesehen? Es ist ein sehr gefährlicher Ort, $n.\n\nDiesen merkwürdigen Bestien dort traue ich nicht für eine Minute! Ich glaube, man nennt sie knorrige Distelwandler und Distelwurzelformer...\n\nIch möchte in das Tal hinein, aber solange es dort von Distelwandlern wimmelt, kehre ich auf keinen Fall dorthin zurück. Und an dieser Stelle kommt Ihr ins Spiel - wenn Ihr einige von ihnen erledigt, würde ich vielleicht doch dorthin zurückkehren. Was meint Ihr, $n? Helft Ihr mir?", objectives = "Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3363] = { title = "Verderbte Liedblume", description = "Nehmt mich auf.", objectives = "Blah.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3364] = { title = "Lieferung des kochend heißen Morgengebräus", description = "Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Furcutter im Anvilmar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Anvilmar schaffen, bevor das Gebräu kalt wird!\n\nIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Anvilmar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.\n\nDanke, $N, und vergesst nicht, mir meinen Becher zurückzubringen!", objectives = "Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3365] = { title = "Den Becher zurückbringen", description = "Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.\n\nHier, bitte $n... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?", objectives = "Bringt Nori Pridedrift den Becher zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3367] = { title = "Suntara-Steine", description = "<Dorius stöhnt.>\n\nIch bin schwer verletzt, $R. Fühle mich... benommen... Alles dreht sich... Innere... Blutungen.\n\nIch muss zurück nach Ironforge. Helft mir, $N.", objectives = "Helft Dorius, zurück nach Ironforge zu kommen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3368] = { title = "Suntara-Steine", description = "Bruder,\n\nwenn Du diesen Brief liest, bin ich nicht mehr. Wie er zu dir gelangt, weiß ich nicht, aber danke und belohne denjenigen, der ihn dir bringt.\n\nZu den Steinen: Es gibt sie wirklich und sie befinden sich im Besitz der Dunkeleisenzwerge. Ihr Anführer, Lathoric der Schwarze, benutzt die Kraft der Steine, um mein Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht. Ihre Gedanken wurden verdreht, sie arbeiten Tag und Nacht, um etwas, das Obsidion heißt, zu vollenden.\n\nHilf ihnen, Bruder. Das ist der letzte Wunsch eines toten Mannes.\n\n- Dorius", objectives = "Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3369] = { title = "Alptraum", description = "Dieser Splitter enthält große Geheimnisse; er ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe, ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, $N, aber ich denke, es ist am besten, wenn Ihr diesen Splitter so schnell wie möglich in die Hände eines weisen Druiden gebt.\n\nIhr müsst Hamuul Runetotem auf der Anhöhe der Ältesten finden. Geht nach Thunder Bluff. Mehr vermag ich Euch nicht zu sagen.", objectives = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3370] = { title = "Alptraum", description = "Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, $N, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt ... \n\nIhr müsst Mathrengyl Bearwalker im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.", objectives = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3371] = { title = "Zwergengerechtigkeit", description = "Wo mein Herz einst schlug, ist jetzt ein leeres Loch, $N. Über den Verlust von Dorius werde ich so schnell nicht hinwegkommen. Ich muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.\n\nKehrt zur sengenden Schlucht zurück und erfüllt seine letzte Bitte. Befreit seine Männer.", objectives = "Kehrt zur Sengenden Schlucht zurück und sucht Dorius' Archäologenteam.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3372] = { title = "Erlöst sie", description = "Befreit sie, $R. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntara sie, ihre Aufgaben weiter zu erfüllen.\n\nDer Altar von Suntara ist der Schlüssel. Geht nach Norden, in die Hügel oberhalb der Höhle... Die Twilight-Hammer bewachen dort ein Relikt. Bringt es herbei und stellt es auf den Altar von Suntara.\n\n<Der sterbende Archäologe bricht zusammen.>", objectives = "Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3373] = { title = "Die Essenz des Eranikus", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", objectives = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3374] = { title = "Die Essenz des Eranikus", description = "Ihr aktiviert den Schwurstein und Itharius spricht Euren Geist direkt durch den Stein an.\n\n\"Indem Ihr die Ladung dieses Schwursteins angenommen habt, erklärt Ihr Euch einverstanden, meiner Sache und der Sache von Yseras Drachenschwarm behilflich zu sein, und die verderbte Seele von Eranikus zu erlösen. Das erste Opfer, eines von vielen, die Ihr ohne Zweifel bringen müsst, ist, mir den Edelstein zu übergeben, der den Teil von Eranikus' Psyche gefesselt hat, der noch über einen freien Willen verfügt.\"\n\n\"Tut dies, $n, und wir werden zusammen an der Erlösung einer Seele arbeiten, die es verdient hat, erlöst zu werden.\"", objectives = "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3375] = { title = "Ersatzphiole", description = "Ähm... Ihr braucht eine weitere Wahrsagephiole? Das soll wohl ein Witz sein! Was habt Ihr denn mit der Ersten angestellt?! Wir haben eine Menge Arbeit vor uns, $R. Diese Phiolen wachsen nun mal nicht auf Bäumen! Eigentlich wünschte ich, es wäre so, dann könnte ich nämlich einfach eine pflücken gehen. Ich habe nämlich keine mehr!\n\nUm Euch eine zu machen, brauch ich Folgendes: Einen Manatrank, ein Stück Kohle und etwas süßen Nektar. Fragt mich ja nicht, warum, bringt mir einfach, was ich brauche, und ich werde Euch eine neue Phiole machen.", objectives = "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Ironforge, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3376] = { title = "Tötet Spitzhauer!", description = "$n... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.\n\nWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!\n\nIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.", objectives = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3377] = { title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.", objectives = "Hört Zamaels Geschichte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3378] = { title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Einer dieser Götzenanbeter muss sie bei sich tragen.\n\nWenn Ihr mein Gebet wiederfindet, bringt es zu Astarii Starseeker in Darnassus. Dass mein Glauben nach den zahllosen widerwärtigen Aktionen, die ich gegen diese Welt und seine Einwohner begangen habe, wiederbelebt wurde, ist vollkommen unwichtig, aber mein Gebet muss gehört werden. Absolution ist das Letzte, was ich erwarte.", objectives = "Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3379] = { title = "Schattenweber", description = "Die Spinnen der Sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.\n\nSeit Kurzem hat sich eine Gruppe von Wilderern in diesem Land eingenistet, die achtlos massenhaft Spinnen töten, ohne darüber nachzudenken, welche Auswirkungen ihre Taten auf Dauer haben können. Die erste Aufgabe, die ich von Euch verlange, ist recht einfach: Findet sie... und macht ihnen ein Ende.\n\nBeginnt Eure Suche im Norden.\n\nWenn Ihr Hilfe benötigt, sprecht mit Schleifer.", objectives = "Tötet die Gruppe der Schattenseidewilderer, die in der Sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3380] = { title = "Der Versunkene Tempel", description = "Es gibt rastlose Geister in dieser Welt, $N. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...\n\nIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Rivetseeker auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.", objectives = "Sucht Marvon Rivetseeker in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3382] = { title = "Eine Mannschaft in Bedrängnis", description = "Wir waren kurz vor der Küste und suchten nach einem sicheren Hafen, um vor Anker zu gehen. Die Sonne war noch keine Stunde untergegangen, als sie angriffen... diese verdammten Naga!\n\nIch weiß nicht genau, wonach sie gesucht haben, aber sie haben es offensichtlich nicht gefunden - sie sind bereits schon einmal wiedergekommen. Einige meiner Späher stehen am Eingang zum Tal Wache, um uns zu warnen, wenn der nächste Angriff kommt.\n\nEs tut mir Leid, dass Ihr gerade jetzt vorbeikommt, $N, aber das liegt nicht in meiner Macht.\n\nSeid Ihr bereit für den Kampf Eures Lebens?", objectives = "Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der HERRIN DES HORIZONTS gegen den Angriff der Naga. Captain Vanessa Beltis muss überleben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3385] = { title = "Der Untermarkt", description = "Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt.\n\nEs kommt noch schlimmer, $n. Sie haben einen Stützpunkt für ihre Operationen hier in der Sengenden Schlucht errichtet. Handelsmeister Kovic führt diese Operationen an und hat enge Verbindungen zu den Dunkeleisenzwergen des Gebietes.\n\nWir müssen hart zuschlagen und den Anführern ein Zeichen setzen. Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Bringt seinen Händlerranzen zurück, sobald die Tat ausgeführt ist.\n\nZum Kessel!", objectives = "Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3402] = { title = "Der Untermarkt", description = "Ich will, dass Ihr Vizzklick in Gadgetzan persönlich die Nachricht von Kovics Niederlage überbringt. Ich bin ziemlich sicher, Kovics Tod wird ihn so erfreuen, dass er Euch eine großartige Belohnung geben wird.", objectives = "Sprecht mit Vizzklick in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3421] = { title = "Rückreise", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3441] = { title = "Göttliche Vergeltung", description = "Hört meine Geschichte, Abenteurer.", objectives = "Lasst Kalaran Windblade seine Geschichte erzählen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3442] = { title = "Die fehlerlose Flamme", description = "Ihr habt die richtige Entscheidung getroffen, $n.\n\nWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.\n\nWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.\n\nIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.\n\nBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.\n\nIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.", objectives = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3443] = { title = "Das Schmieden des Schafts", description = "Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.\n\nDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.", objectives = "Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3444] = { title = "Der runde Stein", description = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.", objectives = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3445] = { title = "Der Versunkene Tempel", description = "Ich habe von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als ich jemals gesehen habe.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt sucht einen Goblin namens Marvon Rivetseeker auf. Genau wie Troyas und ich hat er viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er seine Heimstatt in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.\n\nViel Glück bei Eurer Suche, man hat schon seit längerem nichts mehr von ihm gehört.", objectives = "Sucht Marvon Rivetseeker in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3446] = { title = "In die Tiefen", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Altaren, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art ... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist ... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", objectives = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3447] = { title = "Das Geheimnis des Kreises", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, $n. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", objectives = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3448] = { title = "Die Bürde weitergeben", description = "Kürzlich erhielt ich den Auftrag, Azshara zu untersuchen, einen einst wunderschönen Landstrich, den die Elfen ihr Zuhause nannten. Das war damals, als sie noch Magie praktizierten. Jetzt ist es dort eher gefährlich als schön, aber das hält uns nicht davon ab, jeden Stein umzudrehen, um Hinweise auf unsere Vergangenheit zu erhalten.\n\nEin Gefährte von mir namens Tymor bot mir seine Hilfe bei der Untersuchung dieses Gebietes an, da er ein besonderes Interesse an solchen Dingen hat.\n\nEr besitzt ein kleines Anwesen rechts neben der Halle der Mysterien hier in der Stadt.", objectives = "Sprecht mit Magier Tymor in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3449] = { title = "Arkane Runen", description = "Einstmals wurde Magie von einigen Elfen genauso verehrt wie Elune selbst. Einige ihrer mächtigsten Magier erstellten Runen und Schrifttafeln, die die Regeln des Arkanen zitierten und Einsichten in ihre Funde gaben. Sie ließen sie an öffentlichen Plätzen aufstellen, damit jeder darüber nachdenken konnte.\n\nIch hätte sehr gern Abpausbilder dieser Runen aus den Ruinen von Eldarath. Ich habe ein Set für Euch, mit dem Ihr Abpausbilder herstellen könnt, aber Ihr müsst sie selbst finden. Seid aber vorsichtig, die Forscherliga ist nicht die Einzige, die sich dafür interessiert.", objectives = "Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3450] = { title = "Eine einfache Ladung", description = "Ich will diese Abpausbilder sofort in meinen Turm geliefert haben, aber Ihr müsst nicht den ganzen Weg selbst gehen. Ich werde sie einfach per Luftfracht aus Azshara bringen lassen.\n\nXiggs Fuselighter schuldet mir noch einen oder zwei Gefallen und wird sich bald in der Nähe aufhalten - er wurde zur Küstenpatrouille abkommandiert. Sprecht mit ihm, bevor Ihr weggeht. Er kann Euch eine Leuchtfeuerwaffe geben, damit Ihr ihm signalisieren könnt. Sobald Ihr die Abpausbilder zusammen habt, begebt Euch an den Ort, den er Euch nennt und übergebt sie ihm dann, damit er sie sicher zu meinem Turm bringen kann. Er sollte sich im Hangar im Militärviertel aufhalten.", objectives = "Sprecht mit Xiggs Fuselighter in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3451] = { title = "Signal zum Abholen", description = "Ah, Tymor hat Euch also geschickt, hm? Ja, dem schulde ich noch einen oder zwei Gefallen. Wie war das? Nein, der kleine Teufel. Ja, da kann ich ihm helfen. Ihr braucht also eine Leuchtfeuerwaffe und einen Ort... nichts leichter als das.\n\nKurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der wir eine Landungsplattform gebaut haben. Ihr nehmt diese Leuchtfeuerwaffe und schießt sie dort ab. Ich sehe dann Euer Signal und werde vorbeikommen, um diese... was auch immer er da haben will, mitzunehmen.", objectives = "Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3452] = { title = "Die Ummantelung der Flamme", description = "Wir brauchen noch ein letztes Teil, um die Fackel zu formen.\n\nIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager der Twilight-Hammer finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.", objectives = "Bringt ein Symbol von Ragnaros zu Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3453] = { title = "Die Fackel der Vergeltung", description = "Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.", objectives = "Wartet bis Kalaran Windblade die Fackel der Vergeltung vollendet hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3454] = { title = "Die Fackel der Vergeltung", description = "Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, $n.", objectives = "Nehmt die Fackel der Vergeltung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3461] = { title = "Rückkehr zu Magier Tymor", description = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Ironforge seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein. Klopft einfach bei ihm an, und er soll Euch ja gut bezahlen. Das hier ist nicht gerade ein Spaziergang... das ist schon mal sicher.\n\nDanke nochmals für Eure Hilfe und viel Glück.\n\nOh, das Zeichenset brauche ich nicht. Warum bringt Ihr es nicht selbst Tymor zurück, wenn Ihr ihn besucht?", objectives = "Bringt Magier Tymors Zeichenset zu ihm zurück nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3462] = { title = "Knappe Maltrake", description = "Sprecht mit meinem Gesandten, dem Knappen Maltrake. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist.", objectives = "Sprecht mit dem Knappen Maltrake.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3463] = { title = "Setzt sie in Brand!", description = "Hört gut zu, $N. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.\n\nWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.\n\nIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Elitewachposteneinheiten der Dunkeleisenzwerge, $N.", objectives = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3481] = { title = "Plunder...", description = "Die Truhe scheint verschlossen zu sein.", objectives = "Öffnet die Truhe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3483] = { title = "Signal zum Abholen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3501] = { title = "Im Dutzend besser", description = "Obgleich Ihr wohl niemals eine fehlerlose Draenethystsphäre finden werdet, könnt Ihr zweifelsohne auf Euren Reisen durch dieses Land einige unvollständige Draenethystfragmente entdecken.\n\nEs ist zwar unwahrscheinlich, dass Kum'isha die fehlerhaften Fragmente benutzen kann, um nach Hause zurückzukehren, dennoch können diese Stücke für andere nützliche Zwecke der Draenei dienen.\n\nBringt mir alle fehlerhaften Draenethystfragmente, die Ihr finden könnt, und ich werde Euch belohnen.", objectives = "Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3502] = { title = "Des einen Draeneis Plunder...", description = "Nach einer solchen Zurschaustellung von ekelhafter Gier ist mir richtig übel.\n\nWie dem auch sei, ich werde mich nicht allzu lange mit Eurer materiellen Abhängigkeit beschäftigen.\n\nFür jedes unvollständige Draenethystfragment, das Ihr mir bringt, werde ich Euch mit weiterem Plunder belohnen. Mein Haufen Plunder wird kleiner werden, und der Eurige dafür anwachsen. Auf Draeneor nennen wir das eine Situation, bei der alle nur gewinnen können.", objectives = "Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den Verwüsteten Landen könnte ein Fragment bei sich tragen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3503] = { title = "Treffen mit dem Meister", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3504] = { title = "Verraten", description = "Verräterisches, diebisches Weib! So nenne ich sie... und genau das wird sie immer sein!\n\nIch habe wahrscheinlich einen großen Fehler gemacht, $n. Ich habe einem Blutelfen vertraut. Was schlimmer ist, ich habe einer Frau vertraut!\n\nSie behauptete, in Azshara lägen große Reichtümer... mächtige Gegenstände. Ich sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde ich belohnt. Und wer ist jetzt wohl der Dumme - sie hat sie alle umgebracht.\n\nIch will Rache, $n, aber ich kann es mir nicht leisten, noch jemanden zu schicken. Sucht Ag'tor bei Valormok auf, nördlich des Lagers der Haldarr. Er kann Euch mehr berichten.", objectives = "Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3505] = { title = "Verraten", description = "Das hatte ich mir gedacht.\n\nWir werden unseren Kreuzzug gegen ihre Tagelöhner entlang der westlichen Steilhänge an der nördlichen Halbinsel von Azshara beginnen. Tötet sie mit blutiger Wut - lasst sie wissen, dass sie die falschen Verbündeten verraten haben.\n\nUm sie selbst müsst Ihr Euch jetzt noch nicht kümmern - sie verbringt die meiste Zeit zusammen mit ihren Leibwachen auf der Suche nach Azshara. Es ist wahrscheinlich am klügsten, erst ihre Tagelöhner zu erschlagen und dann ihr persönliches Lager zu suchen. Es wäre weise auszukundschaften, wo wir sie angreifen können. Vielleicht gibt es ja etwas, womit wir sie provozieren können.", objectives = "Tötet 10 Blutelf-Wiederbeschaffer und 10 Blutelf-Feldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3506] = { title = "Verraten", description = "Nach einigen Momenten des Nachdenkens kommt Ihr auf ein paar Ideen, eine davon bringt Euch zum Lächeln: Vielleicht würde die Zerstörung der Kristalle die Blutelfin ärgern, die für das Abschlachten so vieler Orcs und den Verrat an Belgrom verantwortlich ist?\n\nIhr fahrt fort, mehr vom Manuskript und den Bildern zu entschlüsseln und erkennt, dass einer der Kristalle an den Schöpfer des Kreises gebunden ist - die anderen sind an etwas weitaus Finstereres gebunden.\n\nIhr schließt das Buch und beginnt Euch zu entscheiden, welchen Kristall Ihr zerstören wollt.", objectives = "Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Bloodfist nach Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3507] = { title = "Verraten", description = "Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren.\n\nAh, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, $n.", objectives = "Sprecht mit Belgrom Rockmaul in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3508] = { title = "Den Zauberschutz brechen", description = "Ihr seid tollkühn, $n. Es ist eine bewundernswerte Eigenschaft Eurer Art, sich blind in die Schlacht zu stürzen, auch wenn nur wenig oder gar keine Aussicht auf Erfolg besteht. Ich werde Euch behilflich sein, sei es auch nur, um einen einzigen von Razelikhs Dienern fallen zu sehen.\n\nDen Zauberschutz, der auf Razelikhs Untergebenen liegt, zu brechen, kostet Zeit und macht es nötig, rare Artefakte zu erwerben.\n\nSeid still, ich muss erst das Erleuchtungsritual durchführen. Die Information, die ich dabei erhalte, wird mir helfen, Waffen von großer Macht zu schmieden.", objectives = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3509] = { title = "Der Name der Bestie", description = "Es gibt nur eine Möglichkeit, den Dämonenlord und seine Diener zu verletzen. Eine Waffe der Macht muss geschmiedet werden, die seinen wahren Namen trägt.\n\nWird eine solche Waffe geschmiedet, sind der Dämon und alle, die unter seinem Kommando stehen, verwundbar.\n\nIn Azshara residiert eine geringe Gottheit: Lord Arkkoroc. Ihn müsst Ihr aufsuchen. Aber seid gewarnt - wenn man Euch entdeckt, werden seine Diener alles tun, um Euch zu vernichten.\n\nZweifelsohne müsst Ihr einen Preis für solche Informationen bezahlen.", objectives = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3510] = { title = "Der Name der Bestie", description = "Sie tötet meine Kinder, sterbliches Wesen. Sie nennt sich selbst die Herrscherin dieser Meere. Eine falsche Göttin, nichts weiter. Zermalmt sie und bringt mir all ihre Köpfe.\n\nDafür erhaltet Ihr den Namen, den Ihr sucht, und etwas anderes von gleicher Bedeutsamkeit.\n\nSie weilt im Gelege... Genannt wird sie Hetäre.\n\n<Lord Arkkoroc zeigt in Richtung Südwesten.>\n\nGeht!", objectives = "Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3511] = { title = "Der Name der Bestie", description = "Wie versprochen, werde ich den Namen des Dämonenlords enthüllen: Es ist Razelikh der Entweiher. Zuerst muss ich jedoch etwas vorbereiten, das für Eure Reise von äußerster Wichtigkeit ist.\n\nDie Waffe, die Ihr herstellen wollt, benötigt einen Härter. Gebt mir einen Moment Zeit, um das Blut aus diesen Köpfen herauszupressen.\n\n<Lord Arkkoroc drückt die Köpfe mit seinen gigantischen Fäusten zusammen, sodass das Blut aus ihnen herausfließt.>\n\nBringt diesen Härter zurück zu Loramus, zusammen mit dem Namen der Bestie: Rakh'likh.", objectives = "Bringt den Härter zurück zu Loramus Thalipedes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3512] = { title = "Mit Eranikus' eigenen Worten", description = "$N, als Erstes werden wir eine Methode ersinnen, um durch den Edelstein mit Eranikus zu sprechen. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Zwar ist die Essenz, die Ihr mir gegeben habt, stark besudelt, aber es gibt dennoch Hoffnung, dass wir zu ihm durchdringen.\n\nReist weit hinaus in das eisige Land des östlichen Winterspring und sucht einen unserer sterblichen Verbündeten, Umbranse den Geistsprecher. Er ist ein menschliches Medium, der für die Toten spricht. Zwar ist Eranikus noch nicht wirklich tot, trotzdem könnte er uns eine Hilfe sein.", objectives = "Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3513] = { title = "Die runenverzierte Rolle", description = "Die offiziell aussehende Rolle wurde mit einem silbrigen Band eng verschnürt. Ihr seid Euch sicher, dass jemand das hier sehen möchte, aber wer?\n\nEs gibt einen Außenposten im Norden in der Nähe der Grenze von Ashenvale, und wenn die Informationen auf dieser Rolle die Nachtelfen betreffen, dann sollte die Rolle dorthin gebracht werden.", objectives = "Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3514] = { title = "Hordenpräsenz", description = "Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel.\n\nMit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht. Die Horde wird ihre Kundschafter hier nicht tolerieren.\n\n$n, reist zum Krallenbau. Tötet Rynthariel und stellt ein Symbol auf, das alle sehen können. Nehmt diese Hordenflagge mit Euch, $n. Hisst sie im Krallenbau, damit sie es sich zweimal überlegen, bevor sie einen weiteren Boten durch unser Gebiet schicken.", objectives = "Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3517] = { title = "Wissen stehlen", description = "Ich muss zugeben, $n, ich habe das Beste aus meiner Situation in Azshara gemacht. Belgroms Bestrafung hatte schon seine Vorteile.\n\nBevor ich wegging, habe ich einige Nachforschungen angestellt. Ihr wärt überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen.\n\nIch erzähle Euch noch mehr von meinen Geschäften und gebe Euch sogar einen Anteil an meinen Gewinnen, wenn Ihr mir helft, ein paar von den Sachen einzusammeln.\n\nIn den östlichen Ruinen von Eldarath gibt es Schrifttafeln, die ich benötige. Alle vier wurden nach Hochgeborenenhexern benannt. Bringt sie mir und wir können weiterreden.", objectives = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3518] = { title = "Lieferung an Magatha", description = "Die erste Schrifttafel geht an einen weiblichen Tauren... mit Namen Magatha. Sie gehört zu den Ältesten in Thunder Bluff und zu den Befürwortern der Allianz zwischen den Tauren und den Verlassenen. Sie ist mehr als jeder andere der Ältesten der Meinung, dass die Tauren und ihre Lebensart den Verlassenen helfen können, einen Weg zurück zum Menschsein zu finden.\n\nBringt Ihr die Schrifttafel von Beth'Amara. Die Schrifttafel kann das fehlende Glied sein, das sie benötigt, um den Verlassenen zu helfen... das behauptet sie jedenfalls.", objectives = "Bringt die Schrifttafel von Beth'Amara zu Magatha in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3519] = { title = "Ein Freund in Not", description = "Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.\n\nSagt es bitte Dirania Silvershine. Sie wird mir helfen können.\n\nBeeilt Euch... Mir ist so schwindelig...", objectives = "Sprecht mit Dirania Silvershine in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3520] = { title = "Kreischergeister", description = "Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.\n\nNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.\n\nKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.", objectives = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3521] = { title = "Iverrons Gegengift", description = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.\n\nIch brauche Hyazinth-Pilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grell südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.\n\nDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.", objectives = "Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3522] = { title = "Iverrons Gegengift", description = "Das Gegengift ist fertig, $n. Bitte achtet darauf, dass Iverron es auch trinkt.\n\nEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.\n\nMögen Eure Füße beflügelt sein, $n.", objectives = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3523] = { title = "Geißel der Niederungen", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint ein Typ zu sein, dem das nicht viel ausmacht.", objectives = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3524] = { title = "An Land gespült", description = "Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor Kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.\n\nEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?", objectives = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3525] = { title = "Ausschalten des Götzen", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.\n\nSteht Ihr mir bei?", objectives = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3526] = { title = "Goblin-Ingenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n$N, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3527] = { title = "Die Prophezeiung von Mosh'aru", description = "Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Troll-Stadt Zul'Farrak gebracht, westlich von Gadgetzan.\n\nBringt mir die Mosh'aru-Schrifttafeln!\n\nDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.\n\nDie zweite Schrifttafel hat die Wasserbeschwörerin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.\n\nWenn Ihr die Schrifttafeln habt, bringt sie zu mir.", objectives = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3528] = { title = "Der Gott Hakkar", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkari-Blut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", objectives = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3541] = { title = "Lieferung an Jes'rimon", description = "Ich kenne einen Hehler in Orgrimmar. Er wohnt in der Gasse. Er ist ziemlich schwer zu finden, wenn Ihr nicht wisst, wo Ihr suchen sollt. Wenn Ihr Euch dort in einem der höchsten Gebäude umschaut, solltet Ihr ihn jedoch ohne Probleme finden können.\n\nTut mir aber bitte einen Gefallen und posaunt nicht in ganz Kalimdor herum, dass er dort ist und was er so tut, das wäre schlecht für uns beide.\n\nEr wird uns einen mehr als fairen Preis für die Schrifttafel von Jin'yael geben. Ich weiß zwar nicht genau warum, aber Ihr hättet mal sehen sollen, wie aufgeregt er war, als er von ihrem Aufenthaltsort erfahren hat.", objectives = "Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3542] = { title = "Lieferung an Andron Gant", description = "Andron Gant ist mein nächster Kontakt. Normalerweise hält er sich in Undercity auf... ganz in der Nähe des Apothekariums.\n\nEr war ein bisschen redselig, als das Gespräch darauf kam, warum er die Schrifttafel haben wollte. Anscheinend wollen einige der Magier von Undercity die Arkanzauber studieren, die die Hochgeborenen benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.\n\nNehmt die Schrifttafel von Markri und kommt zu mir zurück, um Euch Euren Teil der Belohnung abzuholen.", objectives = "Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3561] = { title = "Lieferung für Erzmagier Xylem", description = "Die letzte Schrifttafel geht an eine sehr gefährliche Person, $N. Hört auf mich, wenn ich Euch sage, dass ich dieser Person viel weniger traue als irgendeiner der anderen, die Ihr in meinem Namen getroffen habt.\n\nErzmagier Xylem hat einen Turm in den Hügeln mit Ausblick auf ganz Azshara. Er ist zwar ein Mensch, aber er benimmt sich wie kein Mensch, den ich jemals getroffen ... oder getötet habe. Er strahlt Macht aus, und ich wage nicht, ihn zu fragen, was er mit der Schrifttafel vorhat.\n\nEr kam zu mir, aber er teilte mir mit, dass seine Leibwache Sanath mir helfen würde, zum Turm zu kommen, wenn ich bereit sei, ihn zu treffen. Sucht nach Sanath im Norden.", objectives = "Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3562] = { title = "Magathas Bezahlung für Jediga", description = "Bringt diese Notiz zu Jediga. Sagt ihr, dass ihre Bezahlung hier auf sie wartet, wenn sie zurückkommt. Und sagt ihr, dass ich mit ihrer Arbeit zufrieden bin.\n\nBeeilt Euch, $n. Sagt Eurer Meisterin, dass ich hier auf sie warten werde.", objectives = "Bringt Magathas Notiz zu Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3563] = { title = "Jes'rimons Bezahlung für Jediga", description = "Bringt diesen Brief zu Jediga. Lasst sie wissen, dass unser Handel vorteilhaft ist und ich mit ihrer Arbeit zufrieden bin.\n\nSagt ihr, sie soll schnell nach Orgrimmar zurückkommen, und Jes'rimon würde gut für sie sorgen.\n\nSagt ihr das! Und, vielleicht benötige ich in Zukunft noch einmal Eure Dienste, $N.", objectives = "Bringt Jes'rimons Notiz zu Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3564] = { title = "Androns Bezahlung für Jediga", description = "Hier... bringt... <hick> das zu Jediga. Viel Glück!", objectives = "Bringt Androns Notiz zu Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3565] = { title = "Xylems Bezahlung für Jediga", description = "Was ist? Oh, ja, Eure Bezahlung. Natürlich.\n\nNehmt das und fort mit Euch. Jediga wartet bestimmt schon voller Geduld auf Eure Rückkehr.", objectives = "Bringt Xylems Notiz zu Jediga in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3566] = { title = "Erhebt Euch, Obsidion!", description = "Es... Es... Es war alles eine Falle.\n\nVergebt... mir.\n\nTötet den Bastard... Tötet ihn für uns... für Thorius.", objectives = "Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3567] = { title = "An die Spitze", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3568] = { title = "Verbreitete Verderbnis", description = "Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.\n\nNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel ... unter anderem.\n\nIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.", objectives = "Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3569] = { title = "Verbreitete Verderbnis", description = "Gebt das Thersa. Vielleicht wird das hier sie heilen... vielleicht aber auch nicht. Wir werden es nicht wissen, solange sie es nicht getrunken hat.", objectives = "Gebt Cuelys Elixier Thersa Windsong in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3570] = { title = "Verbreitete Verderbnis", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3601] = { title = "Kim'jael, fürwahr!", description = "Kim'jael, fürwahr! Wisst Ihr, was Kim'jael für die Blutelfen bedeutet, $N? Kleine Ratte... oder so etwas in der Art. Diese großen Angeber!\n\nSie haben mich angeworben, damit ich ihnen helfe, das Gebiet auszukundschaften und nach einer Art verlorenen Schatz zu suchen. Natürlich habe ich sofort zugegriffen, als sie das Wort 'Schatz' erwähnten und die Summe, die sie mir bezahlen wollten. Aber dann haben sie sich gegen mich gewandt und versucht, mich zu töten... MICH!\n\nDas zeigt einmal mehr, dass einem Blutelfen nicht zu trauen ist.\n\nMein Problem ist: Sie haben immer noch meine Ausrüstung, und ich kann sie nicht wiederbekommen. Helft Ihr mir?", objectives = "Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3602] = { title = "Azsharit", description = "Die uralten Klippenriesen aus dem südlichen Azshara ernähren sich von Felsen und Gebäuden des Landes. Ihre Ausscheidung ist, bedingt durch die Ernährung, ein höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist.\n\nDer südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden, da die Riesen über ein extrem angriffslustiges Naturell verfügen.\n\nIhr sollt nach Süden vorstoßen und genügend Azsharit einsammeln, um den Waffenkörper herzustellen. Meine Teufelshunde werden Euch beim Einsammeln der Kristalle behilflich sein.", objectives = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.\n\nKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3621] = { title = "Die Herstellung von Teufelsbann", description = "Die Waffen können jetzt geschmiedet werden. Ihr müsst den ausgehärteten Azsharit zu jemandem bringen, der die Fähigkeit besitzt, Teufelsenergie zu bändigen.\n\nIm Schlingendorntal gibt es einen solchen Schmied. Galvan der Alte, Anführer des Mithrilordens, wird die Waffen nach Euren Angaben fertigen. Ihr könnt sein Lager zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg finden.\n\nMögen Eure Entschlossenheit und Euer Glaube Euch durch diese Tortur leiten. Solltet Ihr versagen, wisset, dass Euer Gott auf Euch herablächelt, sterbliches Wesen.", objectives = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3625] = { title = "Verzauberte Azsharit-Teufelswaffe", description = "$n, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen.\n\nAußerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern. Aus diesem Grund dürft Ihr den Teufelsfluch erst dann freigeben, wenn der richtige Zeitpunkt gekommen ist!\n\nGebt mir jetzt einen Moment, damit ich Eure Waffen fertigen kann, $n.", objectives = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3626] = { title = "Rückkehr in die Verwüsteten Lande", description = "Die Stunde der Erlösung rückt näher, $n. Ihr müsst mit Eurer neuen Waffe in die Verwüsteten Lande zurückkehren und mit dem Gefallenen Helden der Horde sprechen, um Eure letzte Aufgabe zu erhalten.", objectives = "Kehrt zum Gefallenen Helden der Horde zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3627] = { title = "Das zerbrochene Amulett vereinen", description = "Um den Entweiher zu erreichen, müsst Ihr zunächst das Dreigestirn der Macht zerstören und die Teile des Amuletts beschaffen. Wenn Ihr alle drei Teile beschafft habt, kommt zu mir zurück, und ich werde Euch weitere Anweisungen geben.\n\nGeht, $n! Auf in die Verwüsteten Lande! Sevine, Allistarj und Grol müssen fallen!", objectives = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.\n\nDenkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise ...", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3628] = { title = "Ihr seid Rakh'likh, Dämon", description = "Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den Verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen. Solange Ihr das Amulett habt, könnt Ihr den Unterschlupf erreichen. Nachdem Ihr erst den Unterschlupf erreicht habt, müsst Ihr die Bestie herbeizaubern. Das Amulett ist Euer Schlüssel, $n. Benutzt es auf dem Altar des Entweihers.\n\nFalls Ihr den Entweiher besiegen könnt, bringt sein Horn zurück. Es wird ein Symbol der Hoffnung für alle sein, die es sehen, ein Beweis dafür, dass es tatsächlich Helden in dieser vom Krieg zerrissenen Welt gibt.", objectives = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3629] = { title = "Goblin-Ingenieurskunst", description = "Experten-Ingenieurskunst beinhaltet zwei unterschiedliche Disziplinen: für Gnome und für Goblins. Ich erwähne Goblin-Ingenieurskunst nur, weil ich ein fairer Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob was im Weg herumsteht - auch wenn sie es selbst sind.\n\n$N, lest diese Anleitung. Wenn Ihr lernen wollt, Euch selbst in die Luft zu jagen, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft, es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3630] = { title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n$N, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3631] = { title = "Teufelsross beschwören", description = "Hmpf. Ich sage, Ihr seid nicht vorbereitet, aber das ist nicht meine Entscheidung. Strahad empfindet das anders und es ist seine Entscheidung... dieses Mal.\n\nEr wünscht mit Euch zu sprechen, und das schnell. Ihr werdet ihn immer noch über Ratchet im Brachland finden, in seinem kleinen Turm dort, mit seinen Akolyten.\n\nTrödelt nicht herum.", objectives = "Sprecht mit Strahad Farsan im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3632] = { title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: Gnom und Goblin. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n$N, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark hier in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3633] = { title = "Goblin-Ingenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n$N, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3634] = { title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Ich bin zwar der Meinung, dass es Verschwendung ist, aber Ihr solltet doch etwas über die Gnomen-Spezialisierung wissen. Sie machen Geräte und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3635] = { title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3636] = { title = "Das Licht bringen", description = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, $N.\n\nIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel von Razorfen heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.\n\nStellt Euch auf die Seite des Lichts, $N, und macht diesem bösen Verbund ein Ende.", objectives = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3637] = { title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnomen wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n$N, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", objectives = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3638] = { title = "Der Schwur der Geheimhaltung", description = "Bei der Goblin-Ingenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft! Unsere Baupläne ermöglichen uns, mächtige Bomben und gewaltige Waffen hervorzubringen. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Goblin-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gnomen-Ingenieurskunst.\n\nWenn Ihr immer noch ein Goblin-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.", objectives = "Wenn Ihr ein Goblin-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprocketspring in Gadgetzan sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3639] = { title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte sie gern analysieren, um Möglichkeiten zu erarbeiten, Goblin-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu unterstreichen. Ich brauche Folgendes: Zwanzig große Eisenbomben, zwanzig Stäbe robustes Dynamit und fünf explosive Schafe - und achtet darauf, dass sie gesichert sind!\n\nBringt mir diese Gegenstände und ich werde Euch Eure eigene Goblin-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Goblin-Ingenieurskunstlehrern zu erhalten!", objectives = "Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3640] = { title = "Der Schwur der Geheimhaltung", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.", objectives = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3641] = { title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", objectives = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3642] = { title = "Der Schwur der Geheimhaltung", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, $N.", objectives = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Oglethorpe in Booty Bay sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3643] = { title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, $N. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", objectives = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
