quests[3646] = { title = "Mitgliedskarten-Erneuerung", description = "wird beim Anblick eines sterbenden Jungtiers wütend!", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3647] = { title = "Mitgliedskarten-Erneuerung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3661] = { title = "Elunes Lieblinge?", description = "Wildekins sind unberechenbare Kreaturen, $N. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird.\n\nDiese Kreaturen wurden angeblich von Elune geschaffen und ich bin daran interessiert herauszufinden, ob dies wirklich der Wahrheit entspricht.\n\nVor kurzem habe ich etwas von einer Population von Wildekins gehört, die im Hinterland leben - heimtückische, primitive und wilde Eulenbestien. Man findet sie unter den wild lebenden Tieren dort. Würdet Ihr einige Wildekin-Federn für mich sammeln?", objectives = "Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3681] = { title = "Foliant der Offenbarung", description = "Verzeiht, dass wir Eure Reise unterbrechen, $R, aber ich dachte, Ihr solltet wissen, dass uns vor kurzem eine Meldung aus Stormwind erreicht hat, dass sich Paladine zum Training dort melden sollen.\n\nWenn ich es nicht besser wüsste, würde ich sagen, dass bald etwas Besonderes geschehen wird und es für Euch an der Zeit ist, die Folianten zu studieren.\n\nSucht Duthorian Rall in Stormwind auf. Er trainiert für gewöhnlich Paladine in der Kathedrale des Lichts.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3701] = { title = "Die glimmenden Ruinen von Thaurissan", description = "Begebt Euch zu den glimmenden Ruinen von Thaurissan in der brennenden Steppe und sammelt so viele Informationen wie möglich.\n\nEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, $N. Nehmt Euch vor den Thaurissan-Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.", objectives = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3702] = { title = "Die glimmenden Ruinen von Thaurissan", description = "Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?", objectives = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3721] = { title = "Ein eigener OOX", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3741] = { title = "Hilarys Halskette", description = "Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.\n\nKönnt Ihr die Kette bitte für uns suchen?", objectives = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3761] = { title = "Un'Goro-Erde", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Der Zirkel des Cenarius möchte diese Erde in großen Mengen untersuchen; zieht daher in die Wildnis von Un'Goro und sammelt genug davon für unsere ständig laufenden Forschungen.\n\nDie angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Bringt sie raus zu Ghede; sucht einfach nach den Erdhaufen und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber verärgert ihn lieber nicht!", objectives = "Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3762] = { title = "Erzdruide Runetotem helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3763] = { title = "Erzdruide Staghelm helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", objectives = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3764] = { title = "Un'Goro-Erde", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Ich möchte Wahrheit von Unwahrheit unterscheiden; begebt Euch daher in die Wildnis von Un'Goro und sammelt ausreichend hochwertige Erdproben für unsere ständig laufenden Studien.\n\nIhr glaubt möglicherweise, dass die Aufgabe, etwas zu sammeln, unter Eurer Würde sei; doch mit solch einer Einstellung macht Ihr Euch weder bei mir noch beim Zirkel des Cenarius beliebt. Bringt die Proben zu Jenal, der zweifellos draußen hinter diesem Baum müßig herumlungert; sucht einfach nach den Erdhaufen. Er wird sich um die Logistik kümmern, nicht ich.", objectives = "Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3765] = { title = "Verderbnis in der Fremde", description = "Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.\n\nIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.\n\nMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.\n\nDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener $C sein, so wie Ihr.", objectives = "Reist zu Gershala Nightwhisper in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3781] = { title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich habe vor, dieses Geheimnis zu enthüllen.\n\nBringt das nach unten zu Mathrengyl, und er wird Euch einige Samenkörner geben, mit denen Ihr beginnen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihm kaufen.", objectives = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3782] = { title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich hoffe, dieses Geheimnis für den Zirkel zu enthüllen.\n\nBringt diesen Gutschein zu meiner Tochter Bashana, und sie wird Euch einige Samenkörner geben, damit Ihr uns helfen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihr kaufen.", objectives = "Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3783] = { title = "Sind wir endlich da, Yeti?", description = "Meine Freunde hatten immerzu tolle Ideen. Ich hatte nie das Gefühl mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nFür den Anfang benötige ich dickes Yetifell von Eisdistelyetis. Werdet Ihr helfen? Ihr könnt sie im Südosten finden.", objectives = "Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3784] = { title = "Erzdruide Runetotem helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3785] = { title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie mir hierher in die Enklave. Und belästigt bitte nicht den Erzdruiden; er ist ein sehr beschäftigter Mann und muss nicht jedes Mal gestört werden, wenn jemand mit einer Ladung Morgenkorn zurückkehrt!", objectives = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3786] = { title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie zu mir hierher auf die Anhöhe der Ältesten. Belästigt bitte nicht den Erzdruiden; er wird sehr mit den Forschungsarbeiten beschäftigt sein sowie mit den tausend anderen Sorgen, die er hat!", objectives = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3787] = { title = "Jonespyres Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt in der Festung Feathermoon in Feralas. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", objectives = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3788] = { title = "Jonespyres Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt hier in der Festung Feathermoon. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", objectives = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3789] = { title = "Erzdruide Staghelm helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", objectives = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3790] = { title = "Erzdruide Staghelm helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", objectives = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3791] = { title = "Das Geheimnis des Morgenkorns", description = "Lasst mich offen mit Euch sein, $n. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen. Ich bin ein Forscher - Flüche sind meine Spezialität. Ich habe gehört, dass Morgenkorn unter den richtigen Bedingungen Fähigkeiten verströmt wie andere Kräuter, die in primitiven Flüchen eingesetzt werden.\n\nIch möchte mehr darüber wissen und bitte Euch um Eure Hilfe. Bringt mir 10 Einheiten Morgenkorn und ich werde mich um Euch kümmern.", objectives = "Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3792] = { title = "Morgenkorn für die Festung Feathermoon", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3801] = { title = "Dunkeleisenerbe", description = "Seid gegrüßt, $N. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.", objectives = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3802] = { title = "Dunkeleisenerbe", description = "Ihr findet Fineous Darkvire jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Ironfel an Euch.\n\nBringt Ironfel zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.\n\nSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Ironfel wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.", objectives = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3803] = { title = "Morgenkorn nach Darnassus", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3804] = { title = "Morgenkorn nach Thunder Bluff", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3821] = { title = "Schreckensfels", description = "Sha'ni wurde ausgeschickt, um Berichte über merkwürdige rituelle Aktivitäten zu untersuchen, die vor mehr als drei Wochen von den Feuermagenogern der brennenden Steppe kamen.\n\nGoretooth sagt mir, dass er noch nichts wieder von dieser Gruppe gehört hätte und dass es am besten sei, wenn ich einfach weitermache und mich auf meine Aufgabe konzentriere. Könnt Ihr Euch das vorstellen? Das ist doch meine Frau!\n\nIch kann meinen Posten nicht verlassen, $N, aber ich muss wissen, was aus Sha'ni geworden ist. Reist in die brennende Steppe und sucht nach ihr.", objectives = "Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3822] = { title = "Krom'Grul", description = "Meine ganze Gruppe wurde gefangen genommen, $N. Alle wurden getötet - alle, außer mir.\n\nIhr Anführer Krom'Grul wollte mich für irgendein Ritual aufsparen.\n\nIch wurde von dem Biest an diesen Altar gekettet und brutal misshandelt. Mein körperliches Sein gab nach einer Stunde dieser Folter auf. Die Bestie riss mir dann meinen Ehenasenring aus dem Gesicht und steckte ihn an seinen Finger. Noch niemals habe ich solch eine Rohheit gesehen!\n\nFindet Krom'Grul und erledigt ihn! Bringt meinen Ring zurück zu Thal'trak.\n\nUnd, $N, sagt ihm, dass wir uns wiedersehen werden ... in einem anderen Leben.", objectives = "Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3823] = { title = "Die Feuermagenoger auslöschen", description = "Wir müssen unsere Feinde schlagen, bevor sie uns schlagen!\n\nIch werde es kurz machen, Soldat.\n\nDie Feuermagenoger der brennenden Steppe sind Verbündete der Orcs des Blackrockklans. Sie arbeiten eng mit diesen üblen Orcs zusammen, bewachen den mineralreichen Schreckensfels und halten die Nachschublinien ständig offen.\n\nHinterlasst Euer Zeichen, $N. Legt ihre Streitkräfte lahm und kehrt zu mir zurück, wenn der Auftrag erledigt ist.\n\n<Oralius greift in die Luft und macht eine erwürgende Bewegung.>\n\nICH BRING DICH UM, WINKY!", objectives = "Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3824] = { title = "Gor'tesh der Schläger-Lord", description = "Sie sind gelähmt, ich sag's Euch! Unser nächster Schlag muss entscheidend sein.\n\nDer Lord dieser Bestien, Gor'tesh, muss eliminiert werden. Wichtiger noch, sein Kopf muss zu mir zurückgebracht werden, damit ich die dritte Phase unseres Angriffs auf die Feuermagenoger vorbereiten kann.\n\nSeid gewarnt, Soldat, Gor'tesh regiert nicht vom Schreckensfelsen aus. Stattdessen befindet er sich in einem Gebäude der Blackrockorcs westlich vom Schreckensfelsen.\n\nEure Befehle sind daher einfach. Sucht Gor'tesh und hackt ihm seinen fetten Kopf ab. Kommt zurück, wenn Eure Aufgabe erledigt ist.\n\nKLAPPE HALTEN, WINKY!", objectives = "Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3825] = { title = "Ogerkopf auf einem Pfahl = Party", description = "Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat.\n\nIch habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen. Wenn Ihr das getan habt, seht zu, wie diese feigen Oger um ihr Leben rennen! Nachdem Ihr Euren Spaß hattet, kommt zu mir zurück und ich werde Euch für all Eure harte Arbeit belohnen.\n\n<Oralius scheint seinen Bezug zur Realität zu verlieren.>", objectives = "Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3841] = { title = "Waise sucht Zuhause", description = "Ach, hallo, $n. Ich freue mich sehr, Euch wiederzusehen. Wie war Eure Reise nach Darnassus?\n\nNa, Ihr seid bestimmt froh darüber, dass wir während Eurer Abwesenheit ziemliche Fortschritte gemacht haben. Wir haben sogar ein ganzes Nest voller Eier gerettet. Leider ist die Mutter gestorben, ehe wir sie gefunden haben.\n\nSagt mal, wollt Ihr nicht vielleicht so ein Tierchen haben? Es sieht aus, als würden sie bald schlüpfen, und dann brauchen sie $Geinen guten Vater:eine gute Mutter;. Was meint Ihr?\n\nWenn Ihr wirklich Interesse habt, dann bringt eines der Eier zu Quentin. Ihr findet ihn an der Rennbahn in der Schimmernden Ebene. Er kann Euch mehr darüber sagen.", objectives = "Sprecht mit Quentin in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3842] = { title = "Kurz vor dem Schlüpfen", description = "Die Moonweavers, wie? Überaus interessant. Schade, dass die Grimmlingflitzer nicht schätzen können, was es bedeutet, wenn diese beiden sich um sie kümmern. Beide sind überaus fähig und gut.\n\nSoso, sie haben Euch das Ei also geschenkt. Tja, dann solltet Ihr auch so lange dafür verantwortlich sein, wie Ihr dies wünscht. Das Junge scheint wohl schon bald zu schlüpfen, aber wir sollten trotzdem sichergehen, dass es gesund ist und keinen Schaden genommen hat.\n\nIch brauche lediglich zwei Elixiere der Seelenstärke für einen kleinen Zauber, der das Ei beschützen wird. Die übrigen Komponenten habe ich bereits hier.", objectives = "Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3843] = { title = "Das neueste Mitglied der Familie", description = "Ein prachtvolles Exemplar, $N. Wenn dieses Geschöpf das Heranreifen übersteht, dann wird es ein wahrhaft gesundes Tier sein!\n\nAber eines würde ich Euch noch vorschlagen, wenn Ihr es damit wirklich ernst meint - geht zum Aerie Peak im Hinterland. Sprecht dort mit einem Zwerg namens Agnar Beastamer. Er ist ein Tierführermeister und kann Euch bestimmt bei den letzten Stadien der Brutzeit behilflich sein.\n\nAber eilt Euch, $N, das Ei ist empfindlich und wird sich ohne die richtige Pflege nicht lange halten.", objectives = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3844] = { title = "Es ist für jeden ein Geheimnis", description = "In Ufernähe liegt ein zerstörtes Floß. Das hier ist nur ein kleiner Tümpel, deswegen ist Euch nicht so ganz klar, wie das Floß hier landen konnte. Aber ein Blick auf die Bäume verrät Euch, dass der Wasserstand im Teich nicht unbedingt immer derselbe sein muss.\n\nVielleicht findet Ihr ja mehr heraus, wenn Ihr Euch ein bisschen in der Gegend umschaut ...", objectives = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3845] = { title = "Es ist für jeden ein Geheimnis", description = " Ihr greift nach dem Bündel und zieht es an Land. Vielleicht findet Ihr heraus, wem es gehört, wenn Ihr die Gegenstände darin untersucht.\n\nIn Marshals Zuflucht halten sich ein paar vereinzelte Reisende auf. Vielleicht lässt sich dort ja mehr herausfinden.", objectives = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3861] = { title = "GLUCK!", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.", objectives = "Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3881] = { title = "Rettungsexpedition", description = "Ich weiß zwar nicht, wie Ihr es bis hierher geschafft habt, aber Ihr seid Balsam für meine Augen! Ich heiße Williden Marshal und bin der Leiter eines neutralen Expeditionstrupps. Unsere jüngste und größte Unternehmung wurde von zahllosen Katastrophen begleitet. Die schlimmste davon war, dass wir die Wildheit des Un'Goro Kraters unterschätzt hatten.\n\nAls wir aus unseren Stützpunkten im südwestlichen und nordöstlichen Teil des Kraters flohen, ließen wir lebenswichtige Vorräte zurück. Ihr seht aus, als wärt Ihr recht stark und geschickt ... Könnt Ihr uns vielleicht dabei helfen, sie zurückzubekommen?", objectives = "Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3882] = { title = "Knochenklappern", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marshals Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodons und Dimetrodons graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", objectives = "Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3883] = { title = "Eine fremdartige Ökologie", description = "Nur weil wir einen Rückschlag erlitten haben, heißt das noch lange nicht, dass unsere Forschungen ein Ende finden müssen! Bevor wir hier gelandet sind, untersuchten wir die Schwarmbauten der Gorishiinsekten im südlichen Teil des Kraters. Sie sind fremdartig und passen nicht zur ursprünglichen Ökologie des Un'Goro und wir wollen herausfinden, warum das so ist.\n\nIn ihrem Schwarmbauverbund muss es Larvenbrutstätten geben. Ihr könnt diesen Ort an der hängenden Raupenbrut erkennen. Hier, nehmt mit dieser Phiole eine Probe von der Schwarmbauwand in der Nähe der Brutstätten. Bringt sie dann zu mir zurück, damit ich sie untersuchen kann, aber seid vorsichtig!", objectives = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\n\nBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3884] = { title = "Willidens Tagebuch", description = "Ihr habt ein zerfleddertes Tagebuch zu Tage gefördert. Ein Teil davon ist noch lesbar; es scheint von einem gewissen Williden Marshal verfasst worden zu sein. Wenn das Tagebuch stimmt, dann muss Williden irgendwo im nördlichen Teil des Kraters zu finden sein. Dem Tagebuch zufolge haben er und seine Gefährten in den höheren Lagen des Kraters Schutz gesucht, nachdem ihre tiefer gelegenen Stützpunkte von den wilden Bestien überrannt wurden.", objectives = "Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3901] = { title = "Klappernde Skelette", description = "Ihr habt den Verlassenen Euer Potenzial unter normalen Umständen gezeigt, $N. Jetzt wollen wir mal sehen, wie es damit bestellt ist, wenn Ihr unter Druck steht.\n\nDie klappernden Skelette, weitere hirnlose Diener des Lichkönigs, sind zähere Feinde als die Zombies, mit denen Ihr es bisher zu tun hattet. Auch hier heißt es wieder: Dünnt ihre Reihen aus und beweist den Verlassenen, dass Ihr der Aufgabe gewachsen seid. Frisch ans Werk ... und redet wieder mit mir, wenn Ihr fertig seid.", objectives = "Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3902] = { title = "Beutesuche in Deathknell", description = "Ihr da! Wenn Ihr Euch irgendwie nützlich machen wollt, dann hört zu!\n\nWir benötigen frisch erweckte Rekruten, die sich nach Deathknell begeben und dort nach allem suchen, was wir irgendwie gebrauchen können. Die Dinge werden sich höchstwahrscheinlich in gestapelten Kästen befinden. Wir rechnen damit, dass sich in Kürze weitere Rekruten erheben werden, und wenn wir nicht wollen, dass die nackt herumtappen, dann müssen wir wohl oder übel was für sie suchen.\n\nAlso, macht Euch an die Arbeit, elendes Knochengestell! Und ohne ein bisschen Eile gibt es auch keine Belohnung.", objectives = "Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3903] = { title = "Milly Geltmark", description = "Ihr habt Euch als verlässlich erwiesen, $N. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?\n\nTja, eine Freundin von mir, Milly Osworth, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.", objectives = "Sprecht mit Milly Osworth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3904] = { title = "Millys Ernte", description = "Eine Bande von Briganten, die Defias, sind in die Weinberge von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.\n\nBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie in den Weinbergen im Südosten zurückgelassen.\n\nBringt mir diese Kisten! Rettet meine Ernte!", objectives = "Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3905] = { title = "Traubenliste", description = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.\n\nIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", objectives = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3906] = { title = "Disharmonie der Flamme", description = "Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.\n\nBegebt Euch zum Blackrock und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.\n\nMacht der Störung ein Ende und kehrt dann zu mir zurück.", objectives = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3907] = { title = "Disharmonie des Feuers", description = "Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, $N. Es gibt einen anderen, versteckt in den Tiefen von Blackrock, der diese Verderbtheit kontrolliert.\n\nDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand ... irgendetwas ... gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.\n\nSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.", objectives = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3908] = { title = "Es ist für jeden ein Geheimnis", description = "Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...\n\nAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.\n\nMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir Leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!\n\nNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Snowden in Winterspring. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.", objectives = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3909] = { title = "Das Videre-Elixier", description = "Was sagt Ihr da? Linken... HAT ES VERGESSEN?\n\nAh, verstehe... Hat sein Gedächtnis verloren...\n\nNa gut, hier ist sein Schwert. Es ist aber noch nicht fertig. Ich habe von jemandem gehört, der es fertig stellen kann, aber... tja, es könnte etwas schwierig werden, mit ihm zu reden.\n\nHört mal, ich weiß jemanden, der Euch bestimmt helfen kann. Ich kann Euch jetzt nicht alles erklären, das würde zu lange dauern, aber Ihr müsst Euch irgendwie ein Videre-Elixier beschaffen. Der Einzige, von dem ich weiß, dass er Euch dabei helfen kann, ist Gregan Brewspewer. Er ist ziemlich schwer aufzuspüren, aber zuletzt hatte er ein Lager in der Wildnis von Feralas.", objectives = "Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3912] = { title = "Treffen am Grab", description = "Durch dieses Elixier könnt Ihr mit jemandem sprechen, den Ihr normalerweise nicht einmal sehen würdet...\n\nBringt das Videre-Elixier und Linkens Schwert mit zum Friedhof kurz vor Gadgetzan in Tanaris. Wenn Ihr dort seid, nehmt den Trank zu Euch. Ihr werdet möglicherweise von der Wirkung sehr überrascht sein, aber erschreckt nicht.\n\nGeht in Eurer 'anderen Form' nach Norden, bis Ihr die Berge erreicht. Dort findet Ihr den, mit dem Ihr sprechen müsst, in einer der Felsspalten. Sein Name ist Gaeriyan.\n\nAber vergesst nicht: Nur in dieser Form wird er mit Euch sprechen...", objectives = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3913] = { title = "Grabesstille", description = "Wenn Ihr zum Friedhof zurückkehrt, $n, findet Ihr dort einen Grabstein... Nicht einfach nur irgendeinen Grabstein... Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen.\n\nDrückt gegen den Stein, dann erfahrt Ihr von diesen Geheimnissen...", objectives = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3914] = { title = "Linkens Schwert", description = "Ein greller Lichtblitz blendet Euch, dann könnt Ihr das Schwert wieder aufheben. Es hat sich verwandelt!", objectives = "Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3921] = { title = "Wenikee Kübelbolz", description = "Ich glaube, ich habe das Samophlang zerbrochen. Das ist schlecht, denn ich habe schon einigen Kollegen aus Undermine davon erzählt, und die waren äußerst fasziniert. Wir müssen einen Weg finden, es zu reparieren!\n\nBringt das zerbrochene Samophlang zu Wenikee Boltbucket beim Außenposten der Horde, zwischen dem Brachland und Ashenvale. Sie ist sehr schlau und wissbegierig. Wenn Ihr ihr das Samophlang zeigt, dann, wette ich, stürzt sie sich sofort darauf und will es reparieren.", objectives = "Bringt das zerbrochene Samophlang zu Wenikee Boltbucket.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3922] = { title = "Nugget-Patronen", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Nugget-Patronen mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nDer nächstgelegene Ort, an dem man sie bekommen kann, ist das Schlickermoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Geht ins Schlickermoor und schaut in den Werkzeugkisten nach, die Ihr dort findet. Kommt zu mir zurück, sobald Ihr genug Nugget-Patronen gesammelt habt.", objectives = "Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3923] = { title = "Rilli Schmierklump", description = "Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber ... ich glaube, das würde alles nur noch schlimmer machen.\n\nIhr solltet das Samophlang zu Rilli Greasygob bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.\n\nIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.", objectives = "Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3924] = { title = "Samophlang-Handbuch", description = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Copperplug. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...\n\nBoss Copperplug war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.", objectives = "Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3941] = { title = "Die Hilfe des Gnoms", description = "Ich denke... Ich denke... Ich weiß, dass ich aus irgendeinem wichtigen Grund hergekommen bin...\n\nIch hab da eine Idee, $n. In der Höhle dort drüben wohnt eine Gnomin namens J.D. Sie war sehr freundlich zu mir, als ich hier ankam. Vielleicht habe ich in meiner Verwirrung ihr gegenüber irgendwas erwähnt.\n\nWarum fragt Ihr sie nicht, ob sie etwas weiß? Oh, aber seid vorsichtig: Sie spielt immer mit diesen verrückten, leuchtenden Kristallen herum, die ich im Krater gesehen habe. Ich habe keine Ahnung, was sie da drinnen treibt.", objectives = "Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3942] = { title = "Linkens Andenken", description = "Oh... Linken? Jaaa, der ist echt witzig. Als er hier ankam, murmelte er ständig irgendwelche seltsamen Dinge. Hat wahrscheinlich einen ziemlich heftigen Schlag auf den Kopf bekommen, würde ich mal sagen.\n\nAber etwas, das er gesagt hat, ist bei mir irgendwie hängen geblieben - dass er dabei war, eine Art Totem herzustellen; er sagte, er müsse mit jemandem namens Eridan Bluewind sprechen... an einem Ort namens Teufelswald, glaube ich.\n\nAber ich bezweifle, dass Linken Euch jetzt noch viel darüber sagen kann. Wenn Ihr mehr wissen wollt, solltet Ihr diesen Eridan vielleicht selbst suchen gehen...", objectives = "Sucht Eridan Bluewind im südlichen Teil des Teufelswalds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3961] = { title = "Linkens Abenteuer", description = "Wenn man sich überlegt, dass Linken nur hergekommen ist, um uns von Sturmflamme zu befreien... Er scheint so gar nichts Außergewöhnliches an sich zu haben, aber mir ist aufgefallen, dass er sich überhaupt nicht für meine Experimente oder Geräte interessiert hat, wie das bei den meisten Gnomen sonst der Fall ist. Er muss im Herzen ein echter Krieger sein.\n\nBringt ihm das Totem. Vielleicht hilft ihm das, sich zu erinnern, warum er hergekommen ist.", objectives = "Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3962] = { title = "Allein ist es gefährlich", description = "$n, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen.\n\nAber ich bin kein Held mehr... sondern Ihr. Alles, was Ihr getan habt... Ihr müsst dies jetzt zu Ende bringen, nicht ich.\n\nFindet Sturmflamme und besiegt ihn. Er bewacht ein Artefakt, das die Goldene Flamme genannt wird. Es verleiht mehr Macht als alles, was ich je zuvor gesehen habe, und in den Händen von jemandem, dessen Herz böse ist, ist es äußerst gefährlich.\n\nIhr solltet aber unbedingt Verstärkung mitnehmen - es ist gefährlich, allein zu gehen.", objectives = "Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht.\n\nSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[3981] = { title = "Kommandant Gor'shak", description = "Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...\n\n<Galamav zieht eine Grimasse.>\n\nAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Commander Gor'shak.\n\nFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.\n\nEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!", objectives = "Sucht Kommandant Gor'shak in den Blackrocktiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
